changeSet.sql:
DROP TABLE IF EXISTS analyzer_run CASCADE;
DROP TABLE IF EXISTS analyzer_file_upload CASCADE;
DROP TABLE IF EXISTS analyzer_experiment CASCADE;
DROP TABLE IF EXISTS analyzer_pending_code CASCADE;
DROP TABLE IF EXISTS analyzer_plugin_config CASCADE;
DROP TABLE IF EXISTS qualitative_result_mapping CASCADE;
DROP TABLE IF EXISTS unit_mapping CASCADE;
DROP TABLE IF EXISTS analyzer_field_mapping CASCADE;
DROP TABLE IF EXISTS analyzer_field CASCADE;
DROP TABLE IF EXISTS validation_rule_configuration CASCADE;
DROP TABLE IF EXISTS custom_field_type CASCADE;
DROP TABLE IF EXISTS analyzer_test_map CASCADE;
DROP TABLE IF EXISTS analyzer_type CASCADE;

DROP SEQUENCE IF EXISTS analyzer_type_seq CASCADE;
DROP SEQUENCE IF EXISTS analyzer_experiment_seq CASCADE;

ALTER TABLE analyzer DROP COLUMN IF EXISTS scrip_id CASCADE;
ALTER TABLE analyzer DROP COLUMN IF EXISTS machine_id CASCADE;
ALTER TABLE analyzer DROP COLUMN IF EXISTS analyzer_type CASCADE;
ALTER TABLE analyzer DROP COLUMN IF EXISTS description CASCADE;
ALTER TABLE analyzer DROP COLUMN IF EXISTS location CASCADE;
ALTER TABLE analyzer DROP COLUMN IF EXISTS has_setup_page CASCADE;
ALTER TABLE analyzer DROP COLUMN IF EXISTS analyzer_type_id CASCADE;
ALTER TABLE analyzer DROP COLUMN IF EXISTS identifier_pattern CASCADE;

rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION
        'OGC-1054 analyzer schema cutover is irreversible; restore the pre-cutover backup instead';
END
$$;
